package dispatch

import (
	"context"
	"fmt"
)

type Mode int

const (
	ModeServer Mode = iota
	ModeLocal
)

type TextGenerator interface {
	GenerateText(ctx context.Context, prompt string, model string) (string, error)
}

func (m Mode) String() string {
	switch m {
	case ModeServer:
		return "server"
	case ModeLocal:
		return "local"
	default:
		return fmt.Sprintf("Mode(%d)", m)
	}
}

type Options struct {
	Mode                  Mode
	RepoPaths             []string
	Since                 string
	Until                 string
	Branches              []string
	AllBranches           bool
	ImplicitCurrentBranch bool
	Voice                 string
	InsecureHTTPAuth      bool
	TextGenerator         TextGenerator
	Model                 string
	localPreflight        *localPreflight
}

// CloudRepoLimit caps how many repos the cloud mode may query in one request.
const CloudRepoLimit = 5

func Run(ctx context.Context, opts Options) (*Dispatch, error) {
	if opts.Mode == ModeServer {
		return runServer(ctx, opts)
	}
	return runLocal(ctx, opts)
}
