func TestParseDispatchFlags_JurisdictionNormalized(t *testing.T) {
	t.Parallel()

	opts, err := parseDispatchFlags(
		&cobra.Command{},
		false,
		"7d",
		"",
		false,
		[]string{"entirehq/ferrata"},
		"",
		" US ",
		false,
	)
	if err != nil {
		t.Fatal(err)
	}
	if opts.Jurisdiction != "us" {
		t.Fatalf("expected normalized jurisdiction, got %q", opts.Jurisdiction)
	}
}

func TestParseDispatchFlags_LocalRejectsJurisdiction(t *testing.T) {
	t.Parallel()

	_, err := parseDispatchFlags(
		&cobra.Command{},
		true,
		"7d",
		"",
		false,
		nil,
		"",
		"us",
		false,
	)
	if err == nil || !strings.Contains(err.Error(), "--jurisdiction cannot be used with --local") {
		t.Fatalf("expected local rejection, got %v", err)
	}
}

func TestNewDispatchCmd_JurisdictionFlagHelpText(t *testing.T) {
	t.Parallel()

	cmd := newDispatchCmd()
	flag := cmd.Flags().Lookup("jurisdiction")
	if flag == nil {
		t.Fatal("expected --jurisdiction flag")
	}
	if flag.Shorthand != "j" {
		t.Fatalf("expected -j shorthand to match `entire api`/`entire auth token`, got %q", flag.Shorthand)
	}
	if !strings.Contains(flag.Usage, "home jurisdiction") {
		t.Fatalf("expected usage to explain the home default, got %q", flag.Usage)
	}
	if !strings.Contains(cmd.Long, "--jurisdiction us") {
		t.Fatalf("expected a --jurisdiction example in long help, got %q", cmd.Long)
	}
}
