52	func TestCloudClient_CreateDispatch_Happy(t *testing.T) {
53		t.Parallel()
54	
55		ctx := context.Background()
56		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
57			if r.Method != http.MethodPost || r.URL.Path != testDispatchEndpoint {
58				http.NotFound(w, r)
59				return
60			}
61			if r.Header.Get("Authorization") == "" {
62				w.WriteHeader(http.StatusUnauthorized)
63				return
64			}
65			if r.URL.Query().Has(jurisdictionQueryParam) {
66				t.Errorf("home-jurisdiction request must not send a %s selector, got %q", jurisdictionQueryParam, r.URL.RawQuery)
67			}
68	
69			var body map[string]any
70			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
71				t.Error(err)
72				return
73			}
74			repos, ok := body["repos"].([]any)
75			if !ok || len(repos) != 1 || repos[0] != testRepoFullName {
76				t.Errorf("bad repos payload: %v", body["repos"])
77			}
78			for _, forbidden := range []string{"repo", "wait", "generate", "branches", "orgs", "jurisdiction"} {
79				if _, ok := body[forbidden]; ok {
80					t.Errorf("did not expect %q in request body: %v", forbidden, body)
81				}
82			}
83	
84			w.Header().Set("Content-Type", "application/json")
85			w.WriteHeader(http.StatusAccepted)
86			_, _ = w.Write([]byte(generatingDispatchJSON("run-1"))) //nolint:errcheck // test fixture response
87		}))
88		defer srv.Close()
89	
90		client := newTestCloudClient(t, srv.URL, "t")
91		got, err := client.CreateDispatch(ctx, CreateDispatchRequest{
92			Repos: []string{testRepoFullName},
93			Since: "2026-04-09T00:00:00Z",
94			Until: "2026-04-16T00:00:00Z",
95		}, "")
96		if err != nil {
97			t.Fatal(err)
98		}
99		if got.ID != "run-1" || got.Status != DispatchStatusGenerating {
100			t.Fatalf("unexpected detail: %+v", got)
101		}
102	}
103	
104	func TestCloudClient_CreateDispatch_SendsJurisdictionSelectorAsQueryOnly(t *testing.T) {
105		t.Parallel()
106	
107		ctx := context.Background()
108		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
109			if got := r.URL.Query().Get(jurisdictionQueryParam); got != "us" {
110				t.Errorf("expected ?jurisdiction=us, got query %q", r.URL.RawQuery)
111			}
112			var body map[string]any
113			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
114				t.Error(err)
115				return
116			}
117			if _, ok := body["jurisdiction"]; ok {
